// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSairaCondensed = makeLoadFont('SairaCondensed');

// Load professional sports broadcast style condensed font
const { fontFamily: sairaCondensedFamily } = loadSairaCondensed();



export type LowerThirdProps = Record<string, any>;

const LowerThird: React.FC<LowerThirdProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 25,
  timestamp = "9:50",
  drillName = "Players arrive and get ready",
  schedule = [
    { timestamp: "9:50", drillName: "Players arrive and get ready" },
    { timestamp: "10:00", drillName: "Coach led warmup" },
    { timestamp: "10:10", drillName: "Footwork, passing & technical work" },
    { timestamp: "10:30", drillName: "Shooting & finishing" },
    { timestamp: "10:50", drillName: "Decision making and game scenarios" },
  ],
  limeColor = "#4CAF50",
  charcoalColor = "#1C1C1C",
  textColor = "#FFFFFF",
  bannerScale = 1.0,
  yOffsetPercent = 35,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Detect 9:16 aspect ratio or portrait screens to adjust sizing automatically
  const isPortrait = width < height;

  // Resolve background color with transparency support
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Use the schedule list if provided, otherwise fallback to single items
  const activeSchedule = schedule && schedule.length > 0 
    ? schedule 
    : [{ timestamp, drillName }];

  // Allocate duration equally among all schedule items
  const itemDuration = durationInFrames / activeSchedule.length;

  // Smooth entrance/exit transitions scaled down to fit item duration
  const transitionFrames = Math.min(20, itemDuration * 0.15);

  // Dynamic layout metrics optimized for 9:16 vertical video & standard formats (doubled thickness)
  const responsiveScale = isPortrait ? 0.75 : 1.0;
  const adjustedBannerScale = bannerScale * responsiveScale;

  // At least double the thickness (original was 78 / 105)
  const bannerHeight = (isPortrait ? 156 : 210) * adjustedBannerScale;
  const greenWidth = width * (isPortrait ? 0.35 : 0.38) * bannerScale;
  
  const containerLeft = isPortrait ? width * 0.04 : width * 0.08;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: sairaCondensedFamily }}>
      {/* Container holding the lower thirds stack */}
      <div
        style={{
          position: "absolute",
          left: containerLeft,
          bottom: height * (yOffsetPercent / 100),
          zIndex: 10,
          transition: "none",
          width: width - (containerLeft * 2),
        }}
      >
        {activeSchedule.map((item, i) => {
          // Define unique, non-overlapping timelines for each item
          const startTime = i * itemDuration;
          const localFrame = frame - startTime;
          const isVisible = localFrame >= 0 && localFrame < itemDuration;

          const entranceProgress = interpolate(localFrame, [0, transitionFrames], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.bezier(0.16, 1, 0.3, 1), // Ultra smooth deceleration
          });

          const exitProgress = interpolate(
            localFrame,
            [itemDuration - transitionFrames, itemDuration - 2],
            [1, 0],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.bezier(0.7, 0, 0.84, 0), // Snappy broadcast-style exit slide
            }
          );

          const rowProgress = entranceProgress * exitProgress;
          const yOffset = interpolate(rowProgress, [0, 1], [500, 0]);
          const opacity = isVisible ? interpolate(rowProgress, [0, 0.2, 1], [0, 1, 1]) : 0;

          // Metallic sweep effect timed per-item as it locks into position
          const sweepProgressGreen = interpolate(
            localFrame,
            [15, 32],
            [-200, greenWidth + 100],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          const sweepProgressCharcoal = interpolate(
            localFrame,
            [17, 35],
            [-200, width + 200],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          // Text Reveal animations (Staggered slide-up, timed per-item with offset based on larger banner height)
          const timestampY = interpolate(localFrame, [5, 18], [bannerHeight * 0.6, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.bezier(0.25, 1, 0.5, 1),
          });

          const timestampOpacity = interpolate(localFrame, [5, 15], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          const drillNameY = interpolate(localFrame, [9, 22], [bannerHeight * 0.6, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.bezier(0.25, 1, 0.5, 1),
          });

          const drillNameOpacity = interpolate(localFrame, [9, 19], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                bottom: 0,
                left: 0,
                width: "100%",
                display: isVisible ? "flex" : "none",
                flexDirection: "row",
                alignItems: "center",
                transform: `translateY(${yOffset}px)`,
                opacity: opacity,
                filter: "drop-shadow(0px 16px 24px rgba(0, 0, 0, 0.45))",
                transition: "none",
                pointerEvents: isVisible ? "auto" : "none",
              }}
            >
              {/* Left Side: Solid Lime Green Block */}
              <div
                style={{
                  transform: "skewX(-12deg)",
                  backgroundColor: limeColor,
                  width: greenWidth,
                  height: bannerHeight,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  overflow: "hidden",
                  position: "relative",
                  zIndex: 2,
                  boxShadow: `0 0 35px ${limeColor}25`,
                  border: `1.5px solid ${limeColor}`,
                  borderRight: "none",
                  transition: "none",
                  flexShrink: 0,
                }}
              >
                {/* Shimmer Sweep Overlay */}
                <div
                  style={{
                    position: "absolute",
                    top: 0,
                    bottom: 0,
                    width: "60px",
                    background: "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.4) 50%, rgba(255,255,255,0) 100%)",
                    transform: `translateX(${sweepProgressGreen}px)`,
                    pointerEvents: "none",
                    zIndex: 3,
                    transition: "none",
                  }}
                />

                {/* Unskewed Content Container */}
                <div
                  style={{
                    transform: "skewX(12deg)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    height: "100%",
                    width: "100%",
                    overflow: "hidden",
                    position: "relative",
                    transition: "none",
                  }}
                >
                  {/* Animated Bold Timestamp */}
                  <div
                    style={{
                      color: textColor,
                      fontSize: Math.round(width * (isPortrait ? 0.065 : 0.07) * bannerScale),
                      fontWeight: 900,
                      letterSpacing: "1px",
                      transform: `translateY(${timestampY}px)`,
                      opacity: timestampOpacity,
                      transition: "none",
                    }}
                  >
                    {item.timestamp}
                  </div>
                </div>
              </div>

              {/* Right Side: Charcoal Activity Label Block */}
              <div
                style={{
                  transform: "skewX(-12deg)",
                  backgroundColor: charcoalColor,
                  height: bannerHeight,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "flex-start",
                  paddingLeft: width * (isPortrait ? 0.05 : 0.075) * adjustedBannerScale,
                  paddingRight: width * (isPortrait ? 0.055 : 0.08) * adjustedBannerScale,
                  marginLeft: -15, // Overlap to completely cover subpixel rendering gaps
                  overflow: "hidden",
                  position: "relative",
                  border: "1.5px solid rgba(255, 255, 255, 0.12)",
                  borderLeft: "none",
                  zIndex: 1,
                  transition: "none",
                  maxWidth: width - containerLeft - greenWidth - (isPortrait ? 15 : 40),
                  flexGrow: 1,
                }}
              >
                {/* Shimmer Sweep Overlay */}
                <div
                  style={{
                    position: "absolute",
                    top: 0,
                    bottom: 0,
                    width: "80px",
                    background: "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.2) 50%, rgba(255,255,255,0) 100%)",
                    transform: `translateX(${sweepProgressCharcoal}px)`,
                    pointerEvents: "none",
                    zIndex: 3,
                    transition: "none",
                  }}
                />

                {/* Unskewed Content Container */}
                <div
                  style={{
                    transform: "skewX(12deg)",
                    display: "flex",
                    alignItems: "center",
                    height: "100%",
                    width: "100%",
                    overflow: "hidden",
                    position: "relative",
                    transition: "none",
                  }}
                >
                  {/* Animated Clean Bold Text (With 2-line clamping to prevent clipping) */}
                  <div
                    style={{
                      color: textColor,
                      fontSize: Math.round(width * (isPortrait ? 0.035 : 0.04) * bannerScale),
                      fontWeight: 800,
                      letterSpacing: isPortrait ? "0.5px" : "1.5px",
                      textTransform: "uppercase",
                      transform: `translateY(${drillNameY}px)`,
                      opacity: drillNameOpacity,
                      display: "-webkit-box",
                      WebkitLineClamp: 2,
                      WebkitBoxOrient: "vertical",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      lineHeight: 1.1,
                      width: "100%",
                      transition: "none",
                    }}
                  >
                    {item.drillName}
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default LowerThird;